query:
mutation sitesDeleteNetworkRangeBulk ( $accountId:ID! $deleteNetworkRangeBulkInput:DeleteNetworkRangeBulkInput!) {
	sites ( accountId:$accountId ) {
		deleteNetworkRangeBulk ( input:$deleteNetworkRangeBulkInput  )  {
			networkRange {
				networkRangeId
				name
				rangeType
				subnet
				translatedSubnet
				localIp
				gateway
				vlan
				azureFloatingIp
				gcpLoadBalancerIp
				primaryManagementIp
				secondaryManagementIp
				dhcpSettings {
					dhcpType
					ipRange
					relayGroupId
					dhcpMicrosegmentation
				}
				mdnsReflector
				internetOnly
			}
		}
	}	
}
